# custom ring indices/colors
def rings(out,top,left,bottom,right,mapping):
    k=0;t,b,l,r=top,bottom,left,right
    while t<=b and l<=r:
        if k in mapping:
            c=mapping[k]
            for j in range(l,r+1):out[t][j]=c
            for i in range(t+1,b+1):out[i][r]=c
            if b>t:
                for j in range(r-1,l-1,-1):out[b][j]=c
            if r>l:
                for i in range(b-1,t,-1):out[i][l]=c
        t+=1;b-=1;l+=1;r-=1;k+=1
